{
  "id": 13,
  "knowledge": "Energy Sustainability Classification",
  "description": "Categories equipment based on their energy sustainability index for environmental impact assessment.",
  "definition": "Equipment is classified as 'Green' (ESI > 0.8), 'Intermediate' (ESI between 0.4 and 0.8), or 'High Impact' (ESI < 0.4), with Green indicating environmentally sustainable operations."
}

{
  "id": 27,
  "knowledge": "energyefficiencypercent",
  "description": "Illustrates the meaning and importance of energy efficiency percentages.",
  "definition": "Energy efficiency percentage typically ranges from 10% to 99%. Values below 30% indicate inefficient systems typical of older equipment, 30-60% represent standard efficiency for conventional equipment, 60-80% indicate high-efficiency modern systems, while values above 80% represent cutting-edge technology with optimal efficiency that minimizes energy waste and operational costs."
}

{
  "id": 0,
  "knowledge": "Equipment Efficiency Rating (EER)",
  "description": "A composite metric that evaluates the overall efficiency of equipment based on performance, reliability, and environmental impact.",
  "definition": "EER = \\frac{performanceindex + reliabilityindex}{2} \\times (1 - \\frac{environmentalimpactindex}{10}), \\text{ where higher values indicate more efficient equipment with better performance and lower environmental impact.}"
}

{
  "id": 19,
  "knowledge": "Sustainable Energy Operation",
  "description": "Defines the conditions for energy-sustainable operations in polar environments.",
  "definition": "An operation is considered 'Energy-Sustainable' when it maintains a REC above 70% (meaning more than 70% of energy comes from renewable sources) while maintaining full operational capability and adequate power reserves for at least 48 hours in case of emergency."
}

{
  "id": 9,
  "knowledge": "Renewable Energy Contribution (REC)",
  "description": "Calculates the percentage contribution of renewable energy sources to the total power generation.",
  "definition": "REC = \\frac{renewablemetrics.solar.output\\_w + renewablemetrics.wind.output\\_w}{fuelcelloutputw + renewablemetrics.solar.output\\_w + renewablemetrics.wind.output\\_w} \\times 100, \\text{ where higher values indicate greater reliance on renewable energy.}"
}

{
  "id": 52,
  "knowledge": "Energy Sustainability Classification System (ESCS)",
  "description": "A comprehensive classification system that categorizes operational energy sustainability based on renewable energy contribution percentages.",
  "definition": "Operations are classified into three sustainability levels: 'Energy-Sustainable' WHEN (REC > 70); 'Moderately Sustainable' WHEN (REC > 50 AND REC <= 70); 'Low Sustainability' WHEN (REC <= 50)."
}

{
  "id": 30,
  "knowledge": "Overall Safety Performance Index (OSPI)",
  "description": "Comprehensively evaluates equipment's overall safety performance based on safety index and equipment efficiency rating",
  "definition": "OSPI = safetyindex \u00d7 EER \u00d7 0.8"
}

{
  "id": 35,
  "knowledge": "Resource Self-Sufficiency Index (RSSI)",
  "description": "Measures a polar site's self-sufficiency in terms of resources",
  "definition": "RSSI = 0.6 \u00d7 REC + 0.4 \u00d7 WRMI"
}

{
  "id": 39,
  "knowledge": "Comprehensive Operational Reliability Indicator (CORI)",
  "description": "Comprehensively assesses the overall reliability of polar equipment operations",
  "definition": "CORI = 0.4 \u00d7 EER + 0.4 \u00d7 ORS + 0.2 \u00d7 CRI"
}

{
  "id": 42,
  "knowledge": "Sustainable Polar Operations (SPO)",
  "description": "Defines sustainability standards for polar operations",
  "definition": "Polar operations are defined as 'sustainable' when the site maintains RSSI > 0.7 and EWRII > 0.65, with wastemanagementstatus = 'Normal' and environmentalimpactindex < 6.0."
}
